<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {createIsmClient,type components} from '@ism/api-client';
const props=defineProps<{tenantId:string;token:string}>();const emit=defineEmits<{close:[];assigned:[]}>();
const client=createIsmClient({getAccessToken:()=>props.token});
const form=reactive({target:'',mode:'IMMEDIATE' as 'IMMEDIATE'|'SCHEDULED',from:'',to:''});
const options=ref<{id:string;label:string;modules:components['schemas']['PackageVersion']['modules']}[]>([]),preview=ref<components['schemas']['SubscriptionPreview']>();
const loading=ref(false),busy=ref(false),unknown=ref(false),confirmed=ref(false),error=ref(''),catalogError=ref(''),errorBox=ref<HTMLElement>();
const blocked=computed(()=>Object.values(preview.value?.quotaChanges??{}).some(c=>c.exceedsTarget));let mounted=true,generation=0;
let snapshot='',attempt:{key:string;body:components['schemas']['AssignSubscription']}|null=null;
const fingerprint=()=>JSON.stringify(form);watch(fingerprint,()=>{preview.value=undefined;confirmed.value=false;});
watch(error,async value=>{if(value){await nextTick();errorBox.value?.focus();}});
function utc(v:string){return v.length===16?v+':00':v;}
async function load(){if(busy.value||unknown.value)return;const g=++generation,token=props.token;loading.value=true;catalogError.value='';options.value=[];preview.value=undefined;confirmed.value=false;try{const r=await client.GET('/console/packages');if(!mounted||g!==generation||token!==props.token)return;if(r.error){catalogError.value=r.error.error.message;return;}options.value=r.data.data.filter(p=>p.status==='ACTIVE').flatMap(p=>p.versions.filter(v=>v.status==='PUBLISHED').map(v=>({id:v.id,modules:v.modules,label:`${p.name}（${p.code}） · V${v.versionNo} ${v.name}`})));if(!options.value.some(o=>o.id===form.target))form.target='';}catch{if(mounted&&g===generation)catalogError.value='候选读取失败，请重新读取';}finally{if(mounted&&g===generation)loading.value=false;}}
async function inspect(){if(busy.value||unknown.value||loading.value)return;error.value='';preview.value=undefined;confirmed.value=false;if(!form.target){error.value='请选择有效套餐的已发布版本';return;}if(form.mode==='SCHEDULED'&&!form.from){error.value='请填写未来生效时间（UTC）';return;}const token=props.token,fp=fingerprint();busy.value=true;try{const r=await client.POST('/console/tenants/{tenantId}/subscription-preview',{params:{path:{tenantId:props.tenantId},query:{packageVersionId:form.target}}});if(!mounted||token!==props.token||fp!==fingerprint())return;if(r.error){error.value=r.error.error.message;return;}if(form.mode==='SCHEDULED'&&utc(form.from)<=r.data.data.asOf){error.value='未来生效时间已过，请重新选择';return;}const from=form.mode==='IMMEDIATE'?r.data.data.asOf:utc(form.from);if(form.to&&(utc(form.to)<=from||utc(form.to)<=r.data.data.asOf)){error.value='结束时间必须晚于起始及当前UTC时间';return;}preview.value=r.data.data;snapshot=fp;}catch{if(mounted&&token===props.token)error.value='影响预览失败，请重试';}finally{if(mounted&&token===props.token)busy.value=false;}}
async function save(){if(busy.value)return;if(!attempt){if(!preview.value||blocked.value||!confirmed.value||snapshot!==fingerprint())return;attempt={key:crypto.randomUUID(),body:{packageVersionId:form.target,tenantVersion:preview.value.tenantVersion,activationMode:form.mode,effectiveFrom:form.mode==='IMMEDIATE'?preview.value.asOf:utc(form.from),effectiveTo:form.to?utc(form.to):null,exceptions:{}}};}const token=props.token,wasUnknown=unknown.value;busy.value=true;error.value='';try{const r=await client.POST('/console/tenants/{tenantId}/subscription',{params:{path:{tenantId:props.tenantId},header:{'Idempotency-Key':attempt.key}},body:attempt.body});if(!mounted||token!==props.token)return;if(r.error){unknown.value=wasUnknown||r.response.status>=500;error.value=unknown.value?'分配结果尚未确认，请使用原请求重试；权限变化时请联系管理员核对订阅计划':r.error.error.message;if(!unknown.value){attempt=null;preview.value=undefined;confirmed.value=false;}return;}if(!r.data?.data)throw Error('Unknown receipt');attempt=null;unknown.value=false;emit('assigned');}catch{if(mounted&&token===props.token){unknown.value=true;error.value='分配结果尚未确认，请使用原请求重试，勿重复分配';}}finally{if(mounted&&token===props.token)busy.value=false;}}
onMounted(load);onBeforeUnmount(()=>{mounted=false;generation++;attempt=null;});
</script>
<template><section class="assignment" aria-labelledby="subscription-assignment-title"><h3 id="subscription-assignment-title">分配租户套餐</h3><p>时间均按 UTC 填写。新分配会替换尚未生效的计划，保留历史；到期不会自动恢复旧套餐。提交时会再次核对用量和权限。</p><p v-if="error" ref="errorBox" role="alert" tabindex="-1">{{error}}</p><p v-if="catalogError" role="alert">{{catalogError}}</p><p v-else-if="loading" role="status">正在读取候选…</p><p v-else-if="!options.length">没有可分配的有效套餐已发布版本，请先发布套餐。</p>
<button type="button" :disabled="busy||unknown||loading" @click="load">重新读取套餐候选</button>
<form @submit.prevent="inspect"><fieldset :disabled="busy||unknown||loading"><label for="assign-package">目标套餐版本</label><select id="assign-package" v-model="form.target" required><option value="" disabled>请选择已发布版本</option><option v-for="o in options" :key="o.id" :value="o.id">{{o.label}}</option></select><label for="assign-mode">生效方式</label><select id="assign-mode" v-model="form.mode"><option value="IMMEDIATE">立即生效</option><option value="SCHEDULED">未来生效</option></select><label v-if="form.mode==='SCHEDULED'">起始时间（UTC）<input v-model="form.from" type="datetime-local" required/></label><label>结束时间（UTC，可留空）<input v-model="form.to" type="datetime-local"/></label></fieldset><button type="submit" :disabled="busy||unknown||loading||!options.length">预览分配影响</button></form>
<section v-if="preview" aria-label="套餐分配影响"><h4>确认分配影响</h4><p>目标：{{options.find(o=>o.id===form.target)?.label}}；{{form.mode==='IMMEDIATE'?'立即生效':`起始 ${utc(form.from)} UTC`}}；结束：{{form.to?`${utc(form.to)} UTC`:'无固定结束时间'}}。</p><p>目标已发布模块与额度：</p><ul><li v-for="m in options.find(o=>o.id===form.target)?.modules??[]" :key="m.moduleCode">{{m.moduleCode}}：{{m.enabled?'启用':'停用'}} · {{JSON.stringify(m.quotas)}}</li></ul><p>当前有效版本：{{preview.currentPackageVersionId?(options.find(o=>o.id===preview?.currentPackageVersionId)?.label??'当前版本不在可分配目录，请到订阅计划查看'):'无有效套餐'}}；预览时间 {{preview.asOf}} UTC。将替换 {{preview.replacedFuturePlans}} 个未生效计划。</p><p>失效模块：{{preview.removedModules.length?preview.removedModules.join('、'):'无'}}。</p><p>以下为已接入的模块与额度影响；尚不包含全部菜单、流程和各类资源影响明细。</p><ul><li v-for="(c,code) in preview.quotaChanges" :key="code">{{code}}：上限 {{c.currentLimit}} → {{c.targetLimit}}，已用 {{c.usedValue}}{{c.exceedsTarget?'（超出目标，禁止分配）':''}}</li></ul><p v-if="!Object.keys(preview.quotaChanges).length">没有已识别的额度降低或超量项。</p><ul><li v-for="n in preview.recommendations" :key="n">{{n}}</li></ul><p v-if="blocked" role="alert">实际用量超过目标额度，当前不能分配。</p><label class="check"><input v-model="confirmed" type="checkbox" :disabled="busy||unknown||blocked"/>已核对目标、生效时间、模块额度和未来计划替换影响</label><button v-if="!unknown" type="button" :disabled="busy||blocked||!confirmed" @click="save">确认分配套餐</button></section>
<button v-if="unknown" type="button" :disabled="busy" @click="save">使用原请求重试分配</button><button type="button" :disabled="busy||unknown" @click="emit('close')">取消套餐分配</button></section></template>
<style scoped>.assignment{margin:18px 0;padding:18px;border:1px solid #9ccac6;border-radius:8px;}.assignment p,.assignment li{line-height:1.6;overflow-wrap:anywhere;}fieldset{border:0;padding:0;min-width:0;}select,input:not([type=checkbox]){width:100%;max-width:100%;min-width:0;min-height:44px;font:inherit;}select{border:1px solid #c8d2da;border-radius:5px;padding:8px;}.check{display:flex;align-items:center;gap:10px;}.check input{width:20px;height:20px;flex-shrink:0;}button{width:auto;min-height:44px;padding:0 14px;margin-right:8px;}[role=alert]{color:#a52828;}</style>
